import { Object3D, Mesh, BoxGeometry, PlaneGeometry, Vector3, Euler } from 'three/webgpu';
import {
	MeshBasicNodeMaterial,
	tslFn,
	vec3,
	mix,
	uniform,
	texture,
	uv,
	normalWorld,
	positionLocal,
	blendMode,
	add,
	sub,
	mul,
	abs,
	greaterThan,
	lessThan,
	cond,
	negate,
} from 'three/tsl';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { createSDFText } from '@/text';

export default function createNode(config, ctx) {
	const root = new Object3D();
	root.position.set(0, 0, 0);
	root.rotation.set(0, 0, 0);
	root.scale.set(1, 1, 1);

	// Design tokens
	const COLORS = {
		background: '#0b0b10',
		surface: '#14141a',
		ink: '#16161d',
		paper: '#e8ecf2',
		accent: '#ff2a38',
		gradA: '#101017',
		gradB: '#1a1a22',
	};
	const gradientMaterial = new MeshBasicNodeMaterial({
		color: tslFn(() => {
			const uvCoord = uv();
			// diagonal gradient at 135°, t = (u+v)/2
			const t = mul(add(uvCoord.x, uvCoord.y), 0.5);
			const colA = vec3(uniform(COLORS.gradA));
			const colB = vec3(uniform(COLORS.gradB));
			return mix(colA, colB, t);
		})(),
	});
	gradientMaterial.transparent = false;

	// Helper to create a cell
	function createCell(width, height, depth, center, hasValueLarge, valueText, labelText, isDominant) {
		const group = new Object3D();

		// Slab geometry
		const geom = new BoxGeometry(width, height, depth);
		const mesh = new Mesh(geom, gradientMaterial);
		mesh.position.set(0, 0, depth / 2);
		group.add(mesh);

		// Tick bar
		const tickGeom = new PlaneGeometry(0.4, 0.05);
		const tickMat = new MeshBasicNodeMaterial({
			color: uniform(COLORS.accent),
			emissive: uniform(COLORS.accent),
			emissiveIntensity: 1.3,
			transparent: true,
			alphaTest: 0.01,
		});
		const tick = new Mesh(tickGeom, tickMat);
		// place inside padding (0.5) from top‑left corner
		const pad = 0.5;
		const tickX = -width / 2 + pad + 0.4 / 2;
		const tickY = height / 2 - pad - 0.05 / 2;
		tick.position.set(tickX, tickY, depth + 0.001);
		group.add(tick);

		// Text: value
		const valueStyle = {
			family: hasValueLarge ? 'Lora' : 'Lora',
			fontWeight: 600,
			fontSize: hasValueLarge ? 124 : 68,
			letterSpacing: hasValueLarge ? -0.01 : -0.005,
			lineHeight: hasValueLarge ? 1 : 1.05,
			color: COLORS.ink,
			// use atlas region from config if needed
			atlas: ctx.fontAtlas,
		};
		const valueMesh = createSDFText(valueText, valueStyle, ctx);
		// Position value text: inside padding, vertically centered for value
		const valueY = tickY - 0.05 - pad - (hasValueLarge ? 0.62 : 0.34);
		valueMesh.position.set(-width / 2 + pad, valueY, depth + 0.002);
		group.add(valueMesh);

		// Text: label
		const labelStyle = {
			family: 'JetBrains Mono',
			fontWeight: 400,
			fontSize: 18,
			letterSpacing: 0.08,
			lineHeight: 1.4,
			color: COLORS.ink,
			atlas: ctx.fontAtlas,
		};
		const labelMesh = createSDFText(labelText, labelStyle, ctx);
		const labelY = valueY - (hasValueLarge ? 0.62 : 0.34) - 0.5;
		labelMesh.position.set(-width / 2 + pad, labelY, depth + 0.002);
		group.add(labelMesh);

		// Position the whole cell
		group.position.copy(center);
		root.add(group);
		return group;
	}

	// Grid layout calculations
	const gridWidth = 5.5;
	const gridHeight = 3.5;
	const gutter = 0.25;

	// Dominant cell
	const dominantWidth = 3.25;
	const dominantHeight = 3.5;
	const dominantDepth = 0.06;
	const dominantCenter = new Vector3(-gridWidth / 2 + dominantWidth / 2, 0, 0);
	const dominantCell = createCell(
		dominantWidth,
		dominantHeight,
		dominantDepth,
		dominantCenter,
		true,
		'0.002 mm',
		'Case tolerance, CNC pass',
		true
	);

	// Secondary top cell
	const secWidth = 2.0;
	const secHeight = 1.625;
	const secDepth = 0.06;
	const rightColumnX = -gridWidth / 2 + dominantWidth + gutter + secWidth / 2;
	const topY = gridHeight / 2 - secHeight / 2;
	const topCenter = new Vector3(rightColumnX, topY, 0);
	const topCell = createCell(
		secWidth,
		secHeight,
		secDepth,
		topCenter,
		false,
		'38 h',
		'Power reserve, NA-01',
		false
	);

	// Secondary bottom cell
	const bottomY = -gridHeight / 2 + secHeight / 2;
	const bottomCenter = new Vector3(rightColumnX, bottomY, 0);
	const bottomCell = createCell(
		secWidth,
		secHeight,
		secDepth,
		bottomCenter,
		false,
		'214',
		'Components per calibre',
		false
	);

	// Header caption
	const headerText = 'ATELIER METRICS / Q2 2026';
	const headerStyle = {
		family: 'JetBrains Mono',
		fontWeight: 700,
		fontSize: 18,
		letterSpacing: 0.12,
		lineHeight: 1.4,
		color: COLORS.accent,
		atlas: ctx.fontAtlas,
	};
	const headerMesh = createSDFText(headerText, headerStyle, ctx);
	headerMesh.position.set(-gridWidth / 2, gridHeight / 2 + 0.5, 0);
	root.add(headerMesh);

	// Animation: stagger‑cards + fade‑up
	const cells = [dominantCell, topCell, bottomCell];
	cells.forEach((c) => {
		c.traverse((obj) => {
			if (obj.isMesh) {
				obj.material.transparent = true;
				obj.material.opacity = 0;
				obj.position.y += 0.2;
			}
		});
	});
	gsap.timeline()
		.addLabel('start')
		.from(
			cells.map((c) => c.children.filter((ch) => ch.isMesh)).flat(),
			{
				opacity: 0,
				y: '+=0.2',
				duration: 0.5,
				ease: 'power2.out',
				stagger: 0.08,
			},
			'start'
		);

	// Interaction handlers
	const timelines = new Set();

	root.userData.handlers = {
		pointerdown: (event) => {
			const tl = gsap.to(root.scale, {
				x: 0.97,
				y: 0.97,
				z: 0.97,
				duration: 0.12,
				ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
			});
			timelines.add(tl);
		},
		pointerup: (event) => {
			const tl = gsap.timeline();
			tl.to(root.scale, {
				x: 1.04,
				y: 1.04,
				z: 1.04,
				duration: 0.9,
				ease: 'cubic-bezier(0.165,0.84,0.44,1)',
			});
			tl.to(
				root.scale,
				{
					x: 1,
					y: 1,
					z: 1,
					duration: 0.2,
				},
				'>'
			);
			timelines.add(tl);
		},
	};

	// Cleanup
	root.userData.cleanup = () => {
		// Dispose geometries & materials
		root.traverse((obj) => {
			if (obj.isMesh) {
				if (obj.geometry) obj.geometry.dispose();
				if (obj.material) obj.material.dispose();
			}
		});
		// Kill GSAP timelines
		timelines.forEach((tl) => tl.kill());
		timelines.clear();
	};

	// Apply any cinematic primitives listed in config (none in this spec)
	if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
		config.cinematicPrimitives.forEach((prim) => {
			const fn = ctx.primitives[prim.name];
			if (typeof fn === 'function') {
				fn(root, prim.params);
			}
		});
	}

	return root;
}
